void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await SystemChrome.setPreferredOrientations([DeviceOrientation.landscapeLeft, DeviceOrientation.landscapeRight]);
  await SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky);
  runApp(const ArenaApp());
}

const bg = Color(0xFF081426), cyan = Color(0xFF53E3F5), blue = Color(0xFF3185FF), red = Color(0xFFFF5368);
class ArenaApp extends StatelessWidget { const ArenaApp({super.key}); @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner:false, title:'Mini Arena', theme:ThemeData.dark().copyWith(scaffoldBackgroundColor:bg), home:const ArenaHome()); }

class V { double x,y; V(this.x,this.y); V operator +(V o)=>V(x+o.x,y+o.y); V operator -(V o)=>V(x-o.x,y-o.y); V operator *(double s)=>V(x*s,y*s); double get len=>math.sqrt(x*x+y*y); V norm(){final l=len; return l<.001?V(1,0):V(x/l,y/l);} }
class Fighter { double x,y,vx=0,vy=0,hp=100,anim=0,cool=0; bool ground=false,dead=false; final bool bot; Fighter(this.x,this.y,{this.bot=false}); }
class Shot { double x,y,vx,vy,life=1.6; bool enemy; Shot(this.x,this.y,this.vx,this.vy,this.enemy); }
